package com.example.bivoca;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import org.junit.runner.RunWith;import static org.junit.Assert.*;import com.example.bivoca.utils.SessionManager;import com.example.bivoca.data.api.ApiBaseUrl;import com.google.gson.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
@RunWith(AndroidJUnit4.class) public class QuizFunctionalAvailabilityTest {
 private JsonObject get(String path,SessionManager session)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(ApiBaseUrl.current()+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("Authorization","Bearer "+session.getAccessToken());try{assertEquals(200,c.getResponseCode());try(InputStream in=c.getInputStream()){return JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject();}}finally{c.disconnect();}}
 @Test public void sixMethodsCapacityGetOnly()throws Exception{
  android.content.Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();assertEquals("com.example.bivoca.e2e",context.getPackageName());assertEquals("http://10.0.2.2:3001/api/v1/",ApiBaseUrl.current());assertEquals("true",InstrumentationRegistry.getArguments().getString("freshSyntheticLoginConfirmed"));SessionManager session=new SessionManager(context);assertTrue(session.isLoggedIn());JsonObject user=get("auth/me",session);int id=user.get("id").getAsInt();assertTrue(id>0);assertEquals(id,session.getUserId());assertTrue(user.get("email").getAsString().matches("qa_ft_[ab]@fixture.invalid"));
  JsonArray checks=new JsonArray();for(String method:new String[]{"MIXED","CHALLENGE","CONTEXT","EN_TO_VI","VI_TO_EN","MATCHING"})for(int count:new int[]{0,5,15,17,20,40,60,80,100,-1}){
   String filter=count<0?"posCode=POS_V2_NOUN":"topicCode=V2_COUNT_"+count;int expected=count<0?100:count;String path="quiz/availability?method="+method+"&"+filter;JsonObject result=get(path,session);assertEquals(expected,result.get("quizEligibleCount").getAsInt());assertEquals("MATCHING".equals(method)?"PAIR":"QUESTION",result.get("unit").getAsString());for(JsonElement n:result.getAsJsonArray("enabledCounts"))assertTrue(n.getAsInt()<=expected);if(expected>0&&expected<20)assertEquals(expected,result.get("fallbackUnitCount").getAsInt());JsonObject row=new JsonObject();row.addProperty("method",method);row.addProperty("path",path);row.addProperty("status",200);row.add("response",result);checks.add(row);
  }
  JsonObject evidence=new JsonObject();evidence.addProperty("qaUserId",id);evidence.addProperty("requestCount",61);evidence.addProperty("mutations",0);evidence.add("checks",checks);File dir=new File(context.getFilesDir(),"m16-7/functional-ai");assertTrue(dir.isDirectory()||dir.mkdirs());try(FileOutputStream out=new FileOutputStream(new File(dir,"availability-matrix.json"))){out.write(evidence.toString().getBytes(StandardCharsets.UTF_8));}
 }
 private JsonElement getAny(String path,SessionManager session)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(ApiBaseUrl.current()+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("Authorization","Bearer "+session.getAccessToken());try{assertEquals(200,c.getResponseCode());try(InputStream in=c.getInputStream()){return JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8));}}finally{c.disconnect();}}
 @Test public void ownedSessionAndQuestionGetProof()throws Exception{
  android.content.Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();assertEquals("com.example.bivoca.e2e",context.getPackageName());assertEquals("http://10.0.2.2:3001/api/v1/",ApiBaseUrl.current());SessionManager session=new SessionManager(context);JsonObject user=get("auth/me",session);JsonObject plan=JsonParser.parseString(new String(java.nio.file.Files.readAllBytes(new File(context.getFilesDir(),"owned-session-get-plan.json").toPath()),StandardCharsets.UTF_8).replace("\uFEFF","")).getAsJsonObject();assertEquals(plan.get("qaUserId").getAsInt(),user.get("id").getAsInt());assertEquals("qa_ft_a@fixture.invalid",user.get("email").getAsString());JsonArray rows=new JsonArray();
  for(JsonElement element:plan.getAsJsonArray("sessions")){JsonObject expected=element.getAsJsonObject();String id=expected.get("id").getAsString();JsonObject s=getAny("quiz/sessions/"+id,session).getAsJsonObject();JsonArray q=getAny("quiz/sessions/"+id+"/questions?cursor=0&limit=100",session).getAsJsonArray();assertEquals(id,s.get("sessionId").getAsString());assertEquals(expected.get("version").getAsInt(),s.get("version").getAsInt());assertEquals(expected.get("selected_unit_count").getAsInt(),q.size());java.util.Set<String> ids=new java.util.HashSet<>();for(JsonElement question:q)assertTrue(ids.add(question.getAsJsonObject().get("questionId").getAsString()));JsonObject row=new JsonObject();row.addProperty("sessionId",id);row.addProperty("sessionHttpStatus",200);row.addProperty("questionsHttpStatus",200);row.add("session",s);row.add("questions",q);rows.add(row);}
  File output=new File(context.getFilesDir(),"m16-7/functional-ai/session-get-verification.json");try(FileOutputStream out=new FileOutputStream(output)){out.write(rows.toString().getBytes(StandardCharsets.UTF_8));}
 }
}
